param([ValidateSet('BuildReader')][string]$Mode='BuildReader',[ValidateSet('Release')][string]$Configuration='Release',[switch]$ProductionBuildConfirmed,[switch]$ExecutionAuthorized)
# Release-only compile/link for one pure OFF reader; never invoke a program/help/solver.
$ErrorActionPreference='Stop';$t=Split-Path -Parent $PSScriptRoot;$repo=(Get-Item -LiteralPath $t).Parent.Parent.Parent.Parent.FullName;$logs=Join-Path $t 'logs';$out=Join-Path $t 'outputs'
$buildNote=Join-Path $t 'notes\upl_gpu_public_off_reader_build_r2.json';$cpp=Join-Path $t 'support\upl_gpu_public_off_native_r1.cpp';$readerNote=Join-Path $t 'notes\upl_gpu_public_off_r1.json'
function E([string]$p){$f=Get-Item -LiteralPath $p;[ordered]@{path=$f.FullName;bytes=$f.Length;sha256=(Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash.ToLowerInvariant()}}
function ResolveTaskPath([string]$p){if([IO.Path]::IsPathRooted($p)){$p}else{Join-Path $repo $p}}
function J([string]$p){[IO.File]::ReadAllText((ResolveTaskPath $p))|ConvertFrom-Json}
function V($rows){foreach($r in $rows){$a=E (ResolveTaskPath $r.path);if($a.bytes -ne $r.bytes -or $a.sha256 -ine $r.sha256){throw "Changed frozen artifact: $($r.path)"}}}
function Save([string]$p,$x){if(Test-Path -LiteralPath $p){throw 'Retained receipt protected'};[IO.File]::WriteAllText($p,($x|ConvertTo-Json -Depth 20)+[Environment]::NewLine,(New-Object Text.UTF8Encoding($false)))}
function Call($tool,[string[]]$argv,[string]$label){
 V @($tool);$receipt=Join-Path $logs ($label+'.call.json');$log=Join-Path $logs ($label+'.log');foreach($p in @($receipt,$log)){if(Test-Path -LiteralPath $p){throw 'Retained owned compile/link protected'}}
 [IO.File]::WriteAllBytes($log,[byte[]]@());$started=[DateTime]::UtcNow.ToString('o');$preference=$ErrorActionPreference;$ErrorActionPreference='Continue'
 Push-Location (Join-Path $repo 'src');try{& $tool.path @argv 2>&1|Tee-Object -FilePath $log|Out-Host;$code=$LASTEXITCODE}finally{Pop-Location;$ErrorActionPreference=$preference}
 V @($tool);Save $receipt ([ordered]@{owned_call_exited=$true;exit_code=$code;program=$tool;arguments=$argv;working_directory=(Join-Path $repo 'src');started_utc=$started;ended_utc=[DateTime]::UtcNow.ToString('o');log=(E $log);program_or_component_run=$false;physical_acceptance=$false});if($code){throw 'OFF reader compile/link failed; preserve evidence'};E $receipt
}
if(!$ProductionBuildConfirmed -or !$ExecutionAuthorized){throw 'Root full OFF-reader/builder review and explicit single Release-build authorization required'}
$gpuPath=Join-Path $logs 'upl_gpu_public_Release_r1.build.json';$g=J $gpuPath;$source=J $g.source_freeze.path;$baseline=J $g.baseline.path
if($g.status -ne 'full_authoritative_GPU_Rebuild_passed_no_helper_or_program_run' -or $g.configuration -ne 'Release' -or @($g.objects).Count -ne 110 -or !$g.objects_exclude_main -or !$g.bounded_public_GPU_wiring_candidate_build_only -or @($source.source).Count -ne 265 -or @($source.four_targets).Count -ne 4 -or $source.unchanged_source_count -ne 261 -or @($baseline.other_source).Count -ne 261 -or @($baseline.canonical_GPU).Count -ne 6 -or @($baseline.target_copies).Count -ne 4 -or $source.baseline.sha256 -ine $g.baseline.sha256){throw 'Current authoritative public Release265/4/261/110/protected-six closure required'}
function VerifyCurrent {
 V $g.inputs;V $g.tools;V $g.objects;V @($g.source_freeze,$g.baseline,$g.project_call,$g.isolated_GPU_program);V $source.source;V $source.four_targets;V $baseline.inputs;V $baseline.source_control_receipts;V $baseline.other_source;V $baseline.canonical_GPU
 foreach($r in $baseline.target_copies){V @($r.copy)};foreach($r in $g.runtime){V @($r.original,$r.copy)}
}
VerifyCurrent;$project=J $g.project_call.path;V @($project.program,$project.log);if(!$project.owned_call_exited -or $project.exit_code -ne 0 -or $project.arguments -notcontains '/t:Rebuild'){throw 'Owned authoritative full Rebuild exit0 required'}
$oldPath=Join-Path $logs 'upl_gpu_public_reader_Release_r1.helper.json';$h=J $oldPath;$oldCpp=Join-Path $t 'support\upl_gpu_public_native_r1.cpp'
if($h.status -ne 'actual_authoritative_GPU_objects_helper_linked_not_run' -or $h.fixture -ne 'Reader' -or $h.configuration -ne 'Release' -or $h.source_build.sha256 -ine (E $gpuPath).sha256 -or @($h.objects).Count -ne 110 -or $h.link_object_count -ne 111 -or !$h.exact_link_closure_verified){throw 'Passed current-object non-CNG positive reader recipe required'}
V $h.inputs;V $h.author_files;V $h.transitive_author_include_files;V $h.transitive_project_include_files;V $h.tools;V $h.libraries;V @($h.source_build,$h.program,$h.helper_object,$h.compile_call,$h.link_call)
$cc=J $h.compile_call.path;$lc=J $h.link_call.path;V @($cc.program,$cc.log,$lc.program,$lc.log)
if(!$cc.owned_call_exited -or !$lc.owned_call_exited -or $cc.exit_code -ne 0 -or $lc.exit_code -ne 0 -or @($lc.arguments|Where-Object {$_.EndsWith('bcrypt.lib',[StringComparison]::OrdinalIgnoreCase)}).Count){throw 'Successful non-CNG owned compiler/linker recipe required'}
$oldSourceRows=@($h.author_files|Where-Object {$_.path -ieq $oldCpp});if($oldSourceRows.Count -ne 1){throw 'Old reader source binding not unique'};V $oldSourceRows
$current=@{};foreach($o in $g.objects){$p=[IO.Path]::GetFullPath($o.path);if($current.ContainsKey($p) -or $p -ine (Join-Path $g.no_space_IntDir ([IO.Path]::GetFileName($p)))){throw 'Duplicate/non-flat current GPU object'};$current[$p]=$o}
foreach($o in $h.objects){$p=[IO.Path]::GetFullPath($o.path);if(!$current.ContainsKey($p) -or $o.bytes -ne $current[$p].bytes -or $o.sha256 -ine $current[$p].sha256){throw 'Positive reader objects do not match current public build'}}
$name='upl_gpu_public_off_reader_Release_r2';$folder=Join-Path $out $name;$record=Join-Path $logs ($name+'.helper.json');foreach($p in @($folder,$record)){if(Test-Path -LiteralPath $p){throw 'Retained OFF reader protected'}}
# New OFF CPP is self-contained (project headers plus exactly one AppInfo link identity).
$author=@(E $PSCommandPath;E $buildNote;E $cpp;E $readerNote);$inputs=$author+@(E $gpuPath;E $oldPath)
$obj=Join-Path $folder 'helper.obj';$exe=Join-Path $folder 'upl_gpu_public_off_native_r1.exe';$oldObj=$h.helper_object.path
$ca=@();$fo=0;$fd=0;$src=0;foreach($a in $cc.arguments){if($a.StartsWith('/Fo',[StringComparison]::OrdinalIgnoreCase)){$ca+='/Fo'+$obj;$fo++}elseif($a.StartsWith('/Fd',[StringComparison]::OrdinalIgnoreCase)){$ca+='/Fd'+(Join-Path $folder 'compile.pdb');$fd++}elseif($a -ieq $oldCpp){$ca+=$cpp;$src++}else{$ca+=$a}}
if($fo -ne 1 -or $fd -ne 1 -or $src -ne 1 -or $ca -notcontains '/std:c++17'){throw 'Only source/Fo/Fd compiler substitutions permitted'}
$la=@();$on=0;$hn=0;foreach($a in $lc.arguments){if($a.StartsWith('/OUT:',[StringComparison]::OrdinalIgnoreCase)){$la+='/OUT:'+$exe;$on++}elseif($a -ieq $oldObj){$la+=$obj;$hn++}elseif($a.StartsWith('/PDB:',[StringComparison]::OrdinalIgnoreCase)){throw 'Release recipe unexpectedly has PDB output'}else{$la+=$a}}
if($on -ne 1 -or $hn -ne 1){throw 'Only reader output/helper-object link substitutions permitted'}
$actual=@($la|Where-Object {$_.EndsWith('.obj',[StringComparison]::OrdinalIgnoreCase)}|ForEach-Object {[IO.Path]::GetFullPath($_).ToLowerInvariant()});$expected=@($obj.ToLowerInvariant())+@($g.objects|ForEach-Object {[IO.Path]::GetFullPath($_.path).ToLowerInvariant()})
if($actual.Count -ne 111 -or @($actual|Sort-Object -Unique).Count -ne 111 -or @(Compare-Object @($actual|Sort-Object) @($expected|Sort-Object)).Count){throw 'Exact110 unchanged current GPU object paths plus OFF reader object required'}
$env:VSCMD_SKIP_SENDTELEMETRY='1';$lines=& $env:ComSpec /d /c 'call "D:\Program Files\VS2022\Common7\Tools\VsDevCmd.bat" -arch=x64 -host_arch=x64 >nul && set';if($LASTEXITCODE){throw 'VS environment failed'};foreach($line in $lines){$i=$line.IndexOf('=');if($i -gt 0){[Environment]::SetEnvironmentVariable($line.Substring(0,$i),$line.Substring($i+1),'Process')}}
[void](New-Item -ItemType Directory -Path $folder);$compile=Call $cc.program $ca ($name+'_compile');$link=Call $lc.program $la ($name+'_link')
$runtime=@();foreach($r in $g.runtime){$p=Join-Path $folder ([IO.Path]::GetFileName($r.copy.path));Copy-Item -LiteralPath $r.copy.path -Destination $p;$v=E $p;if($v.bytes -ne $r.copy.bytes -or $v.sha256 -ine $r.copy.sha256){throw 'OFF reader runtime copy differs'};$runtime+=@{original=$r.copy;copy=$v}}
VerifyCurrent;V $inputs;V $h.tools;V $h.libraries
Save $record ([ordered]@{status='actual_authoritative_GPU_objects_helper_linked_not_run';fixture='OffReader';configuration='Release';source_build=(E $gpuPath);source_freeze=$g.source_freeze;baseline=$g.baseline;inputs=$inputs;author_files=$author;author_files_frozen_by_hash_only=$true;transitive_project_include_files=$source.source;transitive_author_include_files=@();program=(E $exe);runtime=$runtime;tools=$h.tools;libraries=$h.libraries;objects=$g.objects;helper_object=(E $obj);link_object_count=111;exact_link_closure_verified=$true;compile_call=$compile;link_call=$link;replayed_helper=(E $oldPath);compiler_source_remaps=1;compiler_output_remaps=2;GPU_object_substitutions=0;GPU_object_directory_changed=$false;current_GPU_objects_reused_without_rebuild=$true;canonical_GPU_unchanged=$true;protected_canonical_GPU_count=6;historical_original_source_paths_revalidated_as_current=$false;reader_is_distinct_from_positive_512_schema=$true;program_or_component_run=$false;offline_reader_only=$true;public_GPU_dynamic_accepted=$false;physical_acceptance=$false})
